enum IntakeStates {
    IDLE,       // motors stopped
    INTAKING,   // rollers pull a game piece in
    HOLDING,    // we have one: stop pulling, keep it
    EJECTING    // rollers push it back out
}

// driver:    intake.setWantedState(EJECTING);
// subsystem: asks "am I allowed to go there from here?"

protected void handleStateTransition(IntakeStates wanted) {
    // look at: wanted, the current state, and the sensors
    // then SET system_state_ to the state we are allowed to be in
}

protected void handleStateTransition(IntakeStates wanted) {
    if (wanted == IntakeStates.IDLE) {
        system_state_ = IntakeStates.IDLE;
    } else if (wanted == IntakeStates.INTAKING) {
        system_state_ = hasPiece() ? IntakeStates.HOLDING : IntakeStates.INTAKING;
    } else if (wanted == IntakeStates.EJECTING) {
        system_state_ = IntakeStates.EJECTING;
    } else {
        system_state_ = IntakeStates.IDLE;   // anything else: be safe
    }
}

@Override
public void updateLogic(double timestamp) {
    switch (system_state_) {
        case INTAKING:
            rollers.setTargetDutyCycle(0.8);
            break;
        case HOLDING:
            rollers.setTargetDutyCycle(0.1);   // just enough to keep it
            break;
        case EJECTING:
            rollers.setTargetDutyCycle(-0.6);
            break;
        case IDLE:
        default:
            rollers.setTargetDutyCycle(0.0);
            break;
    }
}

